#!/usr/bin/env bash
# Full-chain E2E for the readiness bridge:
#
#   probe_runner drives an exec readiness probe through sandbox_runner's
#   /sandbox-exec/ seam and writes /probe-status/<uid> = live=..;ready=..
#          │  (the verdict, keyed by pod uid)
#          ▼
#   joins that verdict onto the k8s Pod object at
#   /pods/<ns>/<name> by metadata.uid, and the verdict OVERRIDES the pod's
#   static status.ready when selecting a Service's endpoints
#          │
#          ▼
#   the pod appears in / stays out of /endpoints/<ns>/<name>
#
# This is the hop from a probe verdict to endpoint membership.
# All four modules run in ONE runtime over the shared store, so a REAL probe
# flip propagates to endpoints selection — nothing is hand-seeded on
# /probe-status/.
#
# Two pods behind Service default/web (selector app=web), each seeded with a
# k8s Pod object carrying metadata.uid:
#   web-ready  rprobe=exec:/bin/true   static status.ready=FALSE
#              → probe flips ready 0→1 → OVERRIDE includes it (proves the probe,
#                not the static field, put it in the endpoint set)
#   web-fail   rprobe=exec:/bin/false  static status.ready=TRUE
#              → probe holds ready=0 → OVERRIDE excludes it (proves the probe can
#                pull a statically-ready pod OUT)
#
# Runs UNPRIVILEGED (null sandboxes; exec is the already-shipped seam).
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
MODULES_DIR="$ROOT/target/fluxor/bcm2712/modules"

. "$ROOT/scripts/fluxor-env.sh"
if [ -z "${FLUXOR_RUNTIME:-}" ]; then
  FLUXOR_RUNTIME="$(nc_fluxor_runtime "$ROOT")"
fi

command -v fluxor >/dev/null || { echo "FAIL: fluxor CLI not on PATH (cargo install --locked --path ../fluxor/tools)"; exit 1; }
for f in "$FLUXOR_RUNTIME" \
         "$MODULES_DIR/sandbox_runner.fmod" \
         "$MODULES_DIR/probe_runner.fmod" ; do
  [ -e "$f" ] || { echo "FAIL: missing $f (fluxor modules build --target bcm2712)"; exit 1; }
done

D="$(mktemp -d /tmp/nc-probe-ep-e2e-XXXXXX)"
trap 'rm -rf "$D"' EXIT
fail() { echo "FAIL: $1"; tail -25 "$D/run.log" 2>/dev/null || true; exit 1; }

# Append one put record to the store's durable log (same wire the store writes:
# [rev:u64][op:u8=1][key_len:u16][val_len:u32][key][val]). Single-writer here —
# no flock, because nothing else has the file open (the runtime is not running).
store_put() { # store_put <key> <value>
  python3 - "$D/store.log" "$1" "$2" <<'PY'
import struct, sys, os
path, key, val = sys.argv[1], sys.argv[2].encode(), sys.argv[3].encode()
fd = os.open(path, os.O_RDWR | os.O_CREAT, 0o644)
with os.fdopen(fd, "r+b") as f:
    data = f.read()
    p, last = 0, 0
    while p + 15 <= len(data):
        rev, op, kl, vl = struct.unpack("<QBHI", data[p:p+15])
        if p + 15 + kl + vl > len(data):
            break
        last, p = rev, p + 15 + kl + vl
    f.truncate(p)
    f.seek(0, 2)
    f.write(struct.pack("<QBHI", last + 1, 1, len(key), len(val)) + key + val)
    f.flush(); os.fsync(f.fileno())
PY
}

store_last() { # store_last <key>  — last-writer value of a key in the log
  python3 - "$D/store.log" "$1" <<'PY'
import struct, sys
data = open(sys.argv[1], "rb").read()
want = sys.argv[2].encode()
p, out = 0, None
while p + 15 <= len(data):
    rev, op, kl, vl = struct.unpack("<QBHI", data[p:p+15])
    if p + 15 + kl + vl > len(data):
        break
    k = data[p+15:p+15+kl]; v = data[p+15+kl:p+15+kl+vl]
    if k == want:
        out = v if op == 1 else None
    p += 15 + kl + vl
print(out.decode() if out is not None else "")
PY
}

store_history() { # store_history <key> — every value ever put, one per line
  python3 - "$D/store.log" "$1" <<'PY'
import struct, sys
data = open(sys.argv[1], "rb").read()
want = sys.argv[2].encode()
p = 0
while p + 15 <= len(data):
    rev, op, kl, vl = struct.unpack("<QBHI", data[p:p+15])
    if p + 15 + kl + vl > len(data):
        break
    k = data[p+15:p+15+kl]; v = data[p+15+kl:p+15+kl+vl]
    if k == want and op == 1:
        print(v.decode(errors="replace"))
    p += 15 + kl + vl
PY
}

echo "== 1. compose the full-chain graph (+ sandbox_runner + probe_runner + endpoints_reconciler) =="
cat > "$D/graph.yaml" <<'YAML'
# Full-chain readiness-bridge fixture: the
# pod-lifecycle pipeline plus the endpoints reconciler, all over the one store.
target: linux
tick_us: 1000
scheduler:
  accept_cycles: true
modules:
  - name: sandbox_runner
  - name: probe_runner
  - name: pj_source
    type: store_source
    prefix: "/pod-specs/"
    flat: 1
    paths: "cmd,rootfs,iso,net,tasks,graph"
    related: "/pod-resolved/:rootfs,cmd"
    watch: "/pod-resolved/"
  - name: pj_art
    type: decision
    params:
      # chronicle-source: modules/app/_chronicle/pod_project.uproc art
      decision: ""
  - name: pj_sandbox
    type: store_effect
    key_prefix: "/sandboxes/"
  - name: pj_rt
    type: decision
    params:
      # chronicle-source: modules/app/_chronicle/pod_project.uproc rt
      decision: "000b000000350001000201000000400100000010060000000000000040020000000100021e00000040030000001206007365656e3d31400400000041"
  - name: pj_runtime
    type: store_effect
    key_prefix: "/pod-runtime/"
  - name: pj_msource
    type: store_source
    prefix: "/pod-specs/"
    flat: 1
    paths: "cmd,rootfs,iso,net,tasks,graph"
  - name: pj_mtl
    type: decision
    params:
      # chronicle-source: modules/app/_chronicle/pod_project.uproc mtl
      decision: ""
  - name: pj_metal
    type: store_effect
    key_prefix: "/metal-sandboxes/"
  # ── image: a reference resolved to a rootfs and an argv ──────────────
  - name: pi_source
    type: store_source
    prefix: "/pod-specs/"
    flat: 1
    paths: "image,image!repo,image!tag,image!flat,rootfs,cmd"
    watch: "/image-rootfs/,/image-config/"
  - name: pi_req
    type: decision
    params:
      # chronicle-source: modules/app/_chronicle/pod_image.uproc rq
      decision: ""
  - name: pi_requests
    type: store_effect
    key_prefix: "/image-requests/"
  - name: pi_ar
    type: decision
    params:
      # chronicle-source: modules/app/_chronicle/pod_image.uproc ar
      decision: ""
  - name: pi_rootfs
    type: store_effect
    key_prefix: "/image-rootfs/"
    flat: 1
    paths: "state,path"
  - name: pi_ac
    type: decision
    params:
      # chronicle-source: modules/app/_chronicle/pod_image.uproc ac
      decision: ""
  - name: pi_config
    type: store_effect
    key_prefix: "/image-config/"
    flat: 1
    paths: "entrypoint!argv,cmd!argv"
  - name: pi_res
    type: decision
    params:
      # chronicle-source: modules/app/_chronicle/pod_image.uproc rs
      decision: ""
  - name: pi_resolved
    type: store_effect
    key_prefix: "/pod-resolved/"
  # ── lifecycle ────────────────────────────────────────────────────────
  - name: pl_source
    type: store_source
    prefix: "/pod-runtime/"
    flat: 1
    ints: "kill_phase,kill_deadline,backoff_until,run_started,paused_since,restarts,was_terminal"
    now: 1
    due: "kill_deadline,backoff_until"
    related: "/pod-specs/:cmd,desired,restart,rootfs,graph,grace#;/sandbox-status/:state,code;/probe-status/:live;/sandboxes/:cmd"
    watch: "/pod-specs/,/sandbox-status/,/probe-status/,/sandboxes/"
  - name: pl_step
    type: decision
    params:
      # chronicle-source: modules/app/_chronicle/pod_lifecycle.uproc st
      decision: ""
  - name: pl_runtime
    type: store_effect
    key_prefix: "/pod-runtime/"
  - name: pl_killd
    type: decision
    params:
      # chronicle-source: modules/app/_chronicle/pod_effect.uproc kl
      decision: ""
  - name: pl_kill
    type: store_effect
    key_prefix: "/sandbox-kill/"
  - name: pl_sbd
    type: decision
    params:
      # chronicle-source: modules/app/_chronicle/pod_effect.uproc sb
      decision: ""
  - name: pl_sandbox
    type: store_effect
    key_prefix: "/sandboxes/"
  - name: pl_mtd
    type: decision
    params:
      # chronicle-source: modules/app/_chronicle/pod_effect.uproc mt
      decision: ""
  - name: pl_metal
    type: store_effect
    key_prefix: "/metal-sandboxes/"
  - name: pl_std
    type: decision
    params:
      # chronicle-source: modules/app/_chronicle/pod_effect.uproc st
      decision: ""
  - name: pl_status
    type: store_effect
    key_prefix: "/pod-lifecycle-status/"
  - name: pl_evd
    type: decision
    params:
      # chronicle-source: modules/app/_chronicle/pod_effect.uproc ev
      decision: ""
  - name: pl_events
    type: store_effect
    key_prefix: "/events/"
  # ── prune ────────────────────────────────────────────────────────────
  - name: pr_source
    type: store_source
    prefix: "/pod-runtime/"
    watch: "/pod-specs/"
  - name: pr_ask
    type: decision
    params:
      # chronicle-source: modules/app/_chronicle/pod_project.uproc ak
      decision: "000c0000003300010002010000004001000000100200000000000000400200000001000203000000400300000001000203000000401e00000041"
  - name: pr_exists
    type: store_effect
    key_prefix: "/pod-specs/"
  - name: pr_prune
    type: decision
    params:
      # chronicle-source: modules/app/_chronicle/pod_project.uproc pr
      decision: "010500000012000100020200000010940100000000000020000b0000002f0001000201000000400100000010040000000000000040020000000100021e00000040030000001200004004000000410a0000002b0001000201000000400100000010000000000000000040020000001200004003000000120000400400000041"
  - name: pr_drop
    type: store_effect
    key_prefix: "/pod-runtime/"
  # Endpoints is PARAMS: Services JOIN the namespace's Pods with the label
  # selector as the join predicate and the probe runner's readiness overriding
  # the static field -> /endpointslices/<ns>/<svc>/<pod>; a slice whose Pod is
  # gone is pruned; and list_children over the slices materialises
  # /endpoints/<ns>/<svc> = "<pod>=<ip>,…" — the document the consumers parse,
  # unchanged. Params from modules/app/_chronicle/endpoints.uproc.
  - name: ep_pairs
    type: store_source
    prefix: "/services/"
    paths: "spec.selector"
    join: "/pods/"
    join_scoped: 2
    join_match: "metadata.labels:spec.selector"
    join_paths: "status.ready,status.podIP,metadata.uid"
    watch: "/pods/,/probe-status/"
  - name: ep_ask
    type: decision
    params:
      # chronicle-source: modules/app/_chronicle/endpoints.uproc ak
      decision: ""
  - name: ep_probe
    type: store_effect
    key_prefix: "/probe-status/"
    flat: 1
    paths: "ready"
  - name: ep_slice
    type: decision
    params:
      # chronicle-source: modules/app/_chronicle/endpoints.uproc sl
      decision: ""
  - name: ep_slices
    type: store_effect
    key_prefix: "/endpointslices/"
  - name: ep_sl_source
    type: store_source
    prefix: "/endpointslices/"
    watch: "/pods/"
  - name: ep_exists
    type: decision
    params:
      # chronicle-source: modules/app/_chronicle/endpoints.uproc ex
      decision: "0011000000480001000201000000400100000010020000000000000040020000000100021c00000040030000001201002f40110000000100021d000000401200000001000203000000401e00000041"
  - name: ep_podexists
    type: store_effect
    key_prefix: "/pods/"
  - name: ep_prune
    type: decision
    params:
      # chronicle-source: modules/app/_chronicle/endpoints.uproc pr
      decision: "010500000012000100020200000010940100000000000020000b0000002f0001000201000000400100000010040000000000000040020000000100021e00000040030000001200004004000000410a0000002b0001000201000000400100000010000000000000000040020000001200004003000000120000400400000041"
  - name: ep_collect
    type: store_effect
    key_prefix: "/endpointslices/"
  - name: ep_svcs
    type: store_source
    prefix: "/services/"
    paths: "spec.selector"
    list_children: "/endpointslices/"
    child_sep: "/"
    watch: "/endpointslices/"
  - name: ep_doc
    type: decision
    params:
      # chronicle-source: modules/app/_chronicle/endpoints.uproc dc
      decision: ""
  - name: ep_write
    type: store_effect
    key_prefix: "/endpoints/"
# Self-edge: the reconciler's own output feeds its `changes` input, allocating a
# module-owned channel the store's namespace.change SUBSCRIBE pushes onto. The
# module never writes this output; it drains pushed events from the input.
wiring:
  - from: sandbox_runner.status
    to: sandbox_runner.changes
  - from: probe_runner.status
    to: probe_runner.changes
  - from: pj_source.status
    to: pj_source.changes
  - from: pj_source.record_out
    to: pj_art.record_in
  - from: pj_art.result_out
    to: pj_sandbox.request_in
    buffer_group: 1
  - from: pj_sandbox.response_out
    to: pj_rt.record_in
  - from: pj_rt.result_out
    to: pj_runtime.request_in
    buffer_group: 2
  - from: pj_msource.status
    to: pj_msource.changes
  - from: pj_msource.record_out
    to: pj_mtl.record_in
  - from: pj_mtl.result_out
    to: pj_metal.request_in
    buffer_group: 3
  - from: pi_source.status
    to: pi_source.changes
  - from: pi_source.record_out
    to: pi_req.record_in
  - from: pi_req.result_out
    to: pi_requests.request_in
    buffer_group: 21
  - from: pi_requests.response_out
    to: pi_ar.record_in
  - from: pi_ar.result_out
    to: pi_rootfs.request_in
    buffer_group: 22
  - from: pi_rootfs.response_out
    to: pi_ac.record_in
  - from: pi_ac.result_out
    to: pi_config.request_in
    buffer_group: 23
  - from: pi_config.response_out
    to: pi_res.record_in
  - from: pi_res.result_out
    to: pi_resolved.request_in
    buffer_group: 24
  - from: pl_source.status
    to: pl_source.changes
  - from: pl_source.record_out
    to: pl_step.record_in
  - from: pl_step.result_out
    to: pl_runtime.request_in
    buffer_group: 4
  - from: pl_runtime.response_out
    to: pl_killd.record_in
  - from: pl_killd.result_out
    to: pl_kill.request_in
    buffer_group: 5
  - from: pl_kill.response_out
    to: pl_sbd.record_in
  - from: pl_sbd.result_out
    to: pl_sandbox.request_in
    buffer_group: 6
  - from: pl_sandbox.response_out
    to: pl_mtd.record_in
  - from: pl_mtd.result_out
    to: pl_metal.request_in
    buffer_group: 7
  - from: pl_metal.response_out
    to: pl_std.record_in
  - from: pl_std.result_out
    to: pl_status.request_in
    buffer_group: 8
  - from: pl_status.response_out
    to: pl_evd.record_in
  - from: pl_evd.result_out
    to: pl_events.request_in
    buffer_group: 9
  - from: pr_source.status
    to: pr_source.changes
  - from: pr_source.record_out
    to: pr_ask.record_in
  - from: pr_ask.result_out
    to: pr_exists.request_in
    buffer_group: 10
  - from: pr_exists.response_out
    to: pr_prune.record_in
  - from: pr_prune.result_out
    to: pr_drop.request_in
    buffer_group: 11
  - from: ep_pairs.status
    to: ep_pairs.changes
  - from: ep_pairs.record_out
    to: ep_ask.record_in
  - from: ep_ask.result_out
    to: ep_probe.request_in
    buffer_group: 91
  - from: ep_probe.response_out
    to: ep_slice.record_in
  - from: ep_slice.result_out
    to: ep_slices.request_in
    buffer_group: 92
  - from: ep_sl_source.status
    to: ep_sl_source.changes
  - from: ep_sl_source.record_out
    to: ep_exists.record_in
  - from: ep_exists.result_out
    to: ep_podexists.request_in
    buffer_group: 93
  - from: ep_podexists.response_out
    to: ep_prune.record_in
  - from: ep_prune.result_out
    to: ep_collect.request_in
    buffer_group: 94
  - from: ep_svcs.status
    to: ep_svcs.changes
  - from: ep_svcs.record_out
    to: ep_doc.record_in
  - from: ep_doc.result_out
    to: ep_write.request_in
    buffer_group: 95
YAML
nc_build_workload "$ROOT" "$D/graph.yaml" "$D/config.bin" "$D/modules.bin"

echo "== 2. materialize a sleeper bundle + seed the service, pods, and pod-specs =="
mkdir -p "$D/slp"

# Service selects app=web.
store_put "/services/default/web" '{"metadata":{"name":"web"},"spec":{"selector":{"app":"web"}}}'

# web-ready: readiness /bin/true (flips 0->1). Static status.ready seeded FALSE,
# so inclusion can ONLY come from the probe override.
store_put "/pods/default/web-ready" '{"metadata":{"name":"web-ready","uid":"pod-ready","labels":{"app":"web"}},"status":{"podIP":"10.0.0.7","ready":false}}'
store_put "/pod-specs/pod-ready"    "cmd=/bin/sleep 60;desired=running;rprobe=exec:/bin/true:1:2:1:1"

# web-fail: readiness /bin/false (holds ready=0). Static status.ready seeded
# TRUE, so exclusion can ONLY come from the probe override pulling it out.
store_put "/pods/default/web-fail" '{"metadata":{"name":"web-fail","uid":"pod-fail","labels":{"app":"web"}},"status":{"podIP":"10.0.0.8","ready":true}}'
store_put "/pod-specs/pod-fail"    "cmd=/bin/sleep 60;desired=running;rprobe=exec:/bin/false:1:2:1:1"

echo "== 3. run the pipeline (sandbox launch + probe cadence ~1s) =="
FLUXOR_STORE_DIR="$D" RUST_LOG="${RUST_LOG:-warn}" timeout 10 "$FLUXOR_RUNTIME" \
  --config "$D/config.bin" --modules "$D/modules.bin" >"$D/run.log" 2>&1 || true

echo "== 4. probe_runner produced a REAL readiness flip on web-ready =="
PR="$(store_last /probe-status/pod-ready)"
[ "$PR" = "live=1;ready=1" ] || fail "pod-ready should be live=1;ready=1, got '$PR'"
store_history /probe-status/pod-ready | head -1 | grep -q 'ready=0' \
  || fail "pod-ready readiness should have STARTED at 0 (proves itself via the probe)"
echo "   /probe-status/pod-ready: ready 0 -> 1"

PF="$(store_last /probe-status/pod-fail)"
case "$PF" in
  *ready=0) echo "   /probe-status/pod-fail: ready held at 0 (/bin/false)";;
  *) fail "pod-fail readiness should be held at 0, got '$PF'";;
esac

echo "== 5. the bridge: endpoints reflect the PROBE verdict, not the static field =="
EP="$(store_last /endpoints/default/web)"
# web-ready: static=false but probe=1 → IN.  web-fail: static=true but probe=0 → OUT.
[ "$EP" = "web-ready=10.0.0.7" ] \
  || fail "endpoints should be exactly 'web-ready=10.0.0.7' (probe override in AND out), got '$EP'"
echo "   /endpoints/default/web: $EP"

echo "== 6. web-ready APPEARED only after the probe passed (disappear->appear) =="
# Every written endpoints doc: web-ready must not have been present before its
# probe flipped (static ready=false kept it out); the final doc contains it.
if store_history /endpoints/default/web | grep -q 'web-fail'; then
  fail "web-fail must NEVER enter the endpoint set (its readiness probe fails)"
fi
store_history /endpoints/default/web | tail -1 | grep -q 'web-ready=10.0.0.7' \
  || fail "web-ready must be in the final endpoint set once its probe passed"
echo "   web-fail never appeared; web-ready appeared on the flip"

echo "== E2E green: readiness bridge closed — a real probe flip reaches Service endpoints via metadata.uid join =="
